import { test, expect } from '@playwright/test';

test.describe('Textarea Character Count Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><form><textarea id="message" maxlength="500" placeholder="Enter your message"></textarea><div id="charCount">0/500</div></form></body></html>');

    // Add JavaScript to handle character counting
    await page.evaluate(() => {
      const textarea = document.getElementById('message');
      const charCount = document.getElementById('charCount');

      if (textarea && charCount) {
        textarea.addEventListener('input', () => {
          charCount.textContent = `${textarea.value.length}/500`;
        });
      }
    });
  });

  test('should display initial character count as 0/500', async ({ page }) => {
    const charCountDisplay = page.getByText('0/500');
    await expect(charCountDisplay).toBeVisible();
  });

  test('should update character count as user types', async ({ page }) => {
    const textarea = page.locator('textarea');
    const charCountDisplay = page.getByText(/\d+\/500/);

    await textarea.fill('Hello World');
    await expect(charCountDisplay).toContainText('11/500');

    await textarea.fill('Hello World! This is a test message.');
    await expect(charCountDisplay).toContainText('37/500');
  });

  test('should prevent typing beyond 500 character limit', async ({ page }) => {
    const textarea = page.locator('textarea');

    // Create a string with 500 characters
    const maxText = 'a'.repeat(500);
    await textarea.fill(maxText);

    // Try to add more characters
    await textarea.press('End');
    await textarea.type('extra');

    // Verify the textarea still contains only 500 characters
    const value = await textarea.inputValue();
    expect(value.length).toBeLessThanOrEqual(500);
  });

  test('should display correct count for 500 character input', async ({ page }) => {
    const textarea = page.locator('textarea');
    const charCountDisplay = page.getByText(/\d+\/500/);

    const maxText = 'a'.repeat(500);
    await textarea.fill(maxText);

    await expect(charCountDisplay).toContainText('500/500');
  });

  test('should update count when text is cleared', async ({ page }) => {
    const textarea = page.locator('textarea');
    const charCountDisplay = page.getByText(/\d+\/500/);

    await textarea.fill('Sample text');
    await expect(charCountDisplay).toContainText('11/500');

    await textarea.clear();
    await expect(charCountDisplay).toContainText('0/500');
  });

  test('should handle paste operations within limit', async ({ page }) => {
    const textarea = page.locator('textarea');
    const charCountDisplay = page.getByText(/\d+\/500/);

    const pasteText = 'This is pasted content with multiple words and sentences.';

    await textarea.focus();
    await page.evaluate((text) => {
      const textarea = document.getElementById('message') as HTMLTextAreaElement;
      textarea.value = text;
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    }, pasteText);

    await expect(charCountDisplay).toContainText(`${pasteText.length}/500`);
  });
});
